package com.airepair.common;
import org.springframework.http.HttpStatus;
public class BusinessException extends RuntimeException { public final HttpStatus status; public BusinessException(HttpStatus status,String message){super(message);this.status=status;} public static BusinessException bad(String s){return new BusinessException(HttpStatus.BAD_REQUEST,s);} public static BusinessException forbidden(){return new BusinessException(HttpStatus.FORBIDDEN,"无权执行此操作");} public static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"记录不存在");} public static BusinessException conflict(){return new BusinessException(HttpStatus.CONFLICT,"工单状态已改变，请刷新后重试");} }
